CREATE TABLE [dbo].[Car_Details]
(
    VIN VARCHAR(50) PRIMARY KEY,
    Make VARCHAR(50),
    Model VARCHAR(50),
    Year INT,
    Variant VARCHAR(50),
    Body VARCHAR(50),
    Color VARCHAR(50),
    Fuel_Type VARCHAR(50),
    Transmission VARCHAR(50),
    Engine_CC INT,
    Price DECIMAL(7,2),
    Updates_at DATETIME DEFAULT GETDATE()
);

